<script>document.addEventListener('DOMContentLoaded',()=>{const body=document.getElementById('po-lines'),template=document.getElementById('po-line-template'),total=document.getElementById('po-total'),money=n=>'$'+(Number(n)||0).toFixed(2),renumber=()=>body.querySelectorAll('.po-line').forEach((row,index)=>{row.querySelector('.po-item').name=`lines[${index}][item_id]`;row.querySelector('.po-quantity').name=`lines[${index}][quantity]`;row.querySelector('.po-cost').name=`lines[${index}][unit_cost]`;}),calculate=()=>{let sum=0;body.querySelectorAll('.po-line').forEach(row=>{const value=(parseFloat(row.querySelector('.po-quantity').value)||0)*(parseFloat(row.querySelector('.po-cost').value)||0);row.querySelector('.po-line-total').textContent=money(value);sum+=value;});total.textContent=money(sum);};document.getElementById('add-po-line')?.addEventListener('click',()=>{body.append(template.content.cloneNode(true));renumber();calculate();});body?.addEventListener('input',calculate);body?.addEventListener('change',event=>{if(event.target.matches('.po-item')){const cost=event.target.selectedOptions[0]?.dataset.cost;if(cost!==undefined)event.target.closest('.po-line').querySelector('.po-cost').value=cost;}calculate();});body?.addEventListener('click',event=>{if(event.target.closest('.remove-po-line')&&body.querySelectorAll('.po-line').length>1){event.target.closest('.po-line').remove();renumber();calculate();}});calculate();});</script>
